<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Egreso #{{ $egreso->id }}</title><style>
@page{size:58mm auto;margin:0}*{box-sizing:border-box}html,body{width:58mm;margin:0;padding:0;background:#fff;color:#000}body{font-family:"Courier New",monospace;font-size:10px;line-height:1.25}.ticket{width:58mm;padding:3mm 2.5mm}.center{text-align:center}.title{font-size:14px;font-weight:bold}.sub{font-size:10px}.sep{border-top:1px dashed #000;margin:5px 0}.row{display:flex;justify-content:space-between;gap:6px;margin:3px 0}.row span:first-child{font-weight:bold}.row span:last-child{text-align:right;word-break:break-word}.amount{text-align:center;font-size:16px;font-weight:bold;margin:7px 0}.detail{white-space:pre-wrap;word-break:break-word}.footer{font-size:8px;text-align:center;margin-top:8px}</style></head><body><div class="ticket">
<div class="center title">CatuDrive</div><div class="center sub">COMPROBANTE DE EGRESO</div><div class="center">#{{ $egreso->id }}</div><div class="sep"></div>
<div class="row"><span>Fecha:</span><span>{{ $egreso->fecha_registro?->format('d/m/Y H:i') ?? '-' }}</span></div><div class="row"><span>Arqueo:</span><span>#{{ $egreso->id_arqueo }}</span></div><div class="row"><span>Estado:</span><span>{{ $egreso->estado }}</span></div><div class="row"><span>Pago:</span><span>{{ $egreso->tipo_pago }}</span></div><div class="row"><span>Tipo:</span><span>{{ $egreso->tipoTransaccion?->codigo ?? '-' }} - {{ $egreso->tipoTransaccion?->transaccion ?? '-' }}</span></div><div class="row"><span>Cajero:</span><span>{{ trim(($egreso->user?->nombres ?? '').' '.($egreso->user?->primer_apellido ?? '')) ?: ($egreso->user?->usuario ?? '-') }}</span></div>
<div class="sep"></div><div><strong>DETALLE</strong></div><div class="detail">{{ $egreso->detalle ?: '-' }}</div><div class="sep"></div><div class="amount">TOTAL: Bs {{ number_format((float)$egreso->monto,2) }}</div><div class="sep"></div><div class="footer">Generado {{ $generadoEn->format('d/m/Y H:i') }}</div></div></body></html>
